const r = await tools.exec_command({"cmd":"python - <<'PY'
import time, pandas as pd, numpy as np
from one.api import ONE
from brainbox.io.one import SessionLoader, SpikeSortingLoader
one=ONE(base_url='https://openalyx.internationalbrainlab.org',silent=True,cache_dir='/app/data/one_cache'); one.load_cache(tag='Brainwidemap')
b=pd.read_csv('code/code_zhang2025/data/bwm_release.csv',index_col=0); eid=b.eid.iloc[0]
print('eid',eid,one.eid2path(eid),one.eid2pid(eid))
s=SessionLoader(one=one,eid=eid)
for what,fn in [('trials',s.load_trials),('wheel',s.load_wheel),('me',lambda:s.load_motion_energy(views=['left']))]:
 t=time.time()
 try:
  fn(); print(what,'ok',time.time()-t)
  x=getattr(s, 'motion_energy' if what=='me' else what); print(x.keys() if hasattr(x,'keys') else x.shape); print(x.head() if hasattr(x,'head') else {k:v.shape for k,v in x.items()})
 except Exception as e: print(what,'ERR',type(e),e)
pid,pname=one.eid2pid(eid); sl=SpikeSortingLoader(pid=pid[0],one=one,eid=eid,pname=pname[0])
t=time.time(); sp,cl,ch=sl.load_spike_sorting(); print('sp',time.time()-t,sp.keys(),len(sp.times),cl.keys(),len(cl.channels),ch.keys())
t=time.time(); m=sl.merge_clusters(sp,cl,ch).to_df(); print('merged',time.time()-t,m.shape,m.columns.tolist()); print(m[['acronym','label']].head(),m.label.value_counts(dropna=False).head())
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":30000});
text(r.output); if(r.session_id) text(`SESSION_ID=${r.session_id}`);

